import{_ as t,o as r,c as n,a2 as a}from"./chunks/framework.vLhlLNVn.js";const i="/assets/adapter-startet-nicht.94Ga1nmg.svg",m=JSON.parse('{"title":"Verbindung und Adapterstart","description":"","frontmatter":{"order":1,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/de/04.fehlerbehebung/01.verbindung-und-start.md"},"headers":[],"relativePath":"de/adapter/wled/fehlerbehebung/verbindung-und-start.md","filePath":"de/adapter/wled/fehlerbehebung/verbindung-und-start.md","lastUpdated":null}'),d={name:"de/adapter/wled/fehlerbehebung/verbindung-und-start.md"};function o(s,e,l,u,h,c){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="verbindung-und-adapterstart" tabindex="-1">Verbindung und Adapterstart <a class="header-anchor" href="#verbindung-und-adapterstart" aria-label="Permalink to &quot;Verbindung und Adapterstart&quot;">​</a></h1><p><a id="adapter-not-start-stop-responding"></a></p><h2 id="warum-startet-der-adapter-nach-einem-update-nicht-oder-reagiert-nicht-mehr" tabindex="-1">Warum startet der Adapter nach einem Update nicht oder reagiert nicht mehr? <a class="header-anchor" href="#warum-startet-der-adapter-nach-einem-update-nicht-oder-reagiert-nicht-mehr" aria-label="Permalink to &quot;Warum startet der Adapter nach einem Update nicht oder reagiert nicht mehr?&quot;">​</a></h2><p><strong>Kurz:</strong> Schau zuerst ins Log der Instanz <code>wled.&lt;Instanz&gt;</code>. Die bekannten Ursachen sind: Voraussetzungen wie die Node.js-Version nicht erfüllt, ein unvollständig installiertes Update, Fehler älterer Adapterversionen und in v0.9.2 ein Polling-Intervall von 0 oder Geräte, die nach dem Start hinzukamen. Die Tabelle unten ordnet die Log-Zeilen zu.</p><h3 id="so-gehst-du-vor" tabindex="-1">So gehst du vor <a class="header-anchor" href="#so-gehst-du-vor" aria-label="Permalink to &quot;So gehst du vor&quot;">​</a></h3><ol><li>Öffne im Admin den Reiter „Log“ und suche die Zeilen der Instanz <code>wled.&lt;Instanz&gt;</code> und die Zeilen <code>host.&lt;Host&gt;</code> direkt nach dem Start der Instanz. Startet der Adapter gar nicht, steht der Fehler oft beim Host mit <code>Caught by controller</code>.</li><li>Vergleiche die Zeilen mit der Tabelle unten und folge der Lösung.</li><li>Starte die Instanz danach neu.</li><li>Bleibt der Fehler, stelle die Log-Stufe der Instanz auf „debug“, starte sie neu und hänge den Log-Auszug an ein <a href="https://github.com/DrozmotiX/ioBroker.wled/issues" target="_blank" rel="noreferrer">GitHub-Issue</a>. Ersetze vorher IP- und MAC-Adressen.</li></ol><h3 id="bekannte-ursachen-und-log-zeilen" tabindex="-1">Bekannte Ursachen und Log-Zeilen <a class="header-anchor" href="#bekannte-ursachen-und-log-zeilen" aria-label="Permalink to &quot;Bekannte Ursachen und Log-Zeilen&quot;">​</a></h3><p><img src="'+i+'" alt="Entscheidungsbaum: Prüfe der Reihe nach, ob die Installation eine zu alte Node.js-Version meldet, ob „Cannot find module“ im Log steht, ob Meldungen alter Versionen erscheinen, ob viele Zeilen „Unable to initialise“ kommen, ob die Last ohne Fehlermeldung hoch ist oder ob ein Gerät nach einem Ausfall nicht mehr reagiert. Passt nichts, hängst du ein Debug-Log an ein GitHub-Issue."></p><table tabindex="0"><thead><tr><th>Log-Zeile (Auszug)</th><th>Ursache</th><th>Lösung</th></tr></thead><tbody><tr><td>Kein Start nach dem Update, die Installation meldet eine zu alte Node.js-Version</td><td>Der Adapter braucht in v0.9.2 Node.js 20 oder neuer, js-controller 6.0.11 oder neuer und Admin 7.6.17 oder neuer.</td><td>Aktualisiere Node.js, js-controller oder Admin.</td></tr><tr><td><code>Caught by controller[0]: Error: Cannot find module &#39;axios&#39;</code></td><td>Das Update wurde nicht vollständig installiert, eine Bibliothek des Adapters fehlt.</td><td>Installiere den Adapter im Reiter „Adapter“ erneut oder eine neuere Version.</td></tr><tr><td><code>[handleStates] TypeError: Cannot read property &#39;initialized&#39; of undefined</code></td><td>Fehler in Versionen vor v0.6.7, behoben in v0.6.7.</td><td>Aktualisiere den Adapter.</td></tr><tr><td><code>Caught by controller[0]: State attribute definition missing for …</code>, danach beendet sich die Instanz</td><td>Fehler in v0.5.x. Seit v0.7.1 ist die Meldung nur noch eine Debug-Meldung ohne Folgen.</td><td>Aktualisiere den Adapter.</td></tr><tr><td>Viele Zeilen <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> und <code>Device 192.168.x.y unavailable (attempt n/5), will retry in … seconds</code></td><td>Ein Gerät ist ausgeschaltet oder nicht erreichbar. Der Adapter läuft, das Log füllt sich aber bei jedem Versuch.</td><td>Schalte das Gerät ein oder lösche es, wenn du es nicht mehr nutzt.</td></tr><tr><td>Nach jedem Fehler eine zweite Zeile <code>Sentry disabled, error caught : …</code></td><td>Der Adapter meldet jeden Fehler doppelt. Es ist derselbe Fehler.</td><td>Werte nur die erste Zeile aus.</td></tr><tr><td>Keine Fehlermeldung, aber der Adapter reagiert nicht mehr und die Last ist hoch</td><td>„Intervall in Sekunden“ steht auf 0. Die Abfragen laufen dann ohne Pause.</td><td>Stelle das Intervall auf mindestens 1 Sekunde, voreingestellt sind 30 Sekunden.</td></tr><tr><td>Keine Fehlermeldung, aber ein Gerät reagiert nach einem Ausfall nicht mehr</td><td>Das Gerät kam nach dem Adapterstart dazu, über „Neue Geräte suchen“, per IP oder weil die Bonjour-Suche es erst später fand. Für solche Geräte startet in v0.9.2 keine Überwachung, sie verbinden sich nach einem Ausfall nicht neu.</td><td>Starte die Instanz neu.</td></tr></tbody></table><p>Die beiden Zeilen zu <code>State attribute definition missing</code> und <code>Cannot read property &#39;initialized&#39;</code> stammen aus alten Versionen. Siehst du sie heute noch, läuft bei dir eine alte Adapterversion.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Die Einstellung „Maximale Wiederholungsversuche“ gilt für alle Geräte der Instanz gemeinsam. Eine Einstellung je Gerät gibt es nicht.</p></div><h3 id="ab-v0-9-3" tabindex="-1">Ab v0.9.3 <a class="header-anchor" href="#ab-v0-9-3" aria-label="Permalink to &quot;Ab v0.9.3&quot;">​</a></h3><p><strong>Ab v0.9.3:</strong> Der Adapter braucht Node.js 22 oder neuer und Admin 7.6.20 oder neuer. Prüfe das vor dem Update.</p><p><strong>Ab v0.9.3:</strong> Ein Polling-Intervall unter 1 Sekunde oder eine ungültige Zahl an Wiederholungen ersetzt der Adapter beim Start durch den Standard und warnt einmal: <code>Invalid polling interval &quot;0&quot;, using 30 seconds</code> oder <code>Invalid number of retry attempts &quot;0&quot;, using 5</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/924" target="_blank" rel="noreferrer">#924</a>). Korrigiere dann die Einstellung, damit die Warnung verschwindet.</p><p><strong>Ab v0.9.3:</strong> Ein Ausfall steht im Log als eine Warnung, zum Beispiel <code>Unable to initialise 192.168.x.y will retry in scheduled interval !</code> oder <code>Heartbeat of device 192.168.x.y failed, will try to reconnect</code>. Die weiteren Versuche stehen nur noch auf der Stufe „debug“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/903" target="_blank" rel="noreferrer">#903</a>, <a href="https://github.com/DrozmotiX/ioBroker.wled/issues/788" target="_blank" rel="noreferrer">#788</a>).</p><p><strong>Ab v0.9.3:</strong> Jeder Fehler steht nur einmal im Log. Die Übergabe an Sentry steht nur noch auf der Stufe „debug“ (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/913" target="_blank" rel="noreferrer">#913</a>).</p><p><strong>Ab v0.9.3:</strong> Auch Geräte, die nach dem Start dazukommen, werden überwacht und verbinden sich nach einem Ausfall ohne Neustart neu (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/901" target="_blank" rel="noreferrer">#901</a>). <code>_info._online</code> wird <code>false</code>, wenn ein Gerät zwei Polling-Intervalle lang nicht antwortet (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/900" target="_blank" rel="noreferrer">#900</a>).</p><p><strong>Ab v0.9.3:</strong> Einen Befehl an ein Gerät, das offline ist, verwirft der Adapter mit der Warnung <code>Device &lt;MAC&gt; (192.168.x.y) is offline, command for &lt;State&gt; discarded</code> (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/904" target="_blank" rel="noreferrer">#904</a>). <code>on</code> und <code>bri</code> behalten beim Offline-Gehen und beim Adapterstart ihren letzten Wert (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/899" target="_blank" rel="noreferrer">#899</a>).</p><p><strong>Siehe auch:</strong> <a href="./befehle-wirken-nicht#script-not-ps-wled-ignores">Warum setzt mein Skript ps oder on nicht?</a> · <a href="./../erste-schritte/installation#wled-firmware-requirements-adapter-need">Welche Voraussetzungen braucht der Adapter?</a> · <a href="./../referenz/instanz-einstellungen#often-adapter-retry-offline-device">Wie oft versucht der Adapter ein Offline-Gerät erneut zu erreichen?</a> · <a href="./../referenz/log-meldungen#warning-state-attribute-definition-missing">Was bedeutet „State attribute definition missing“?</a></p><p><a id="adapter-stop-working-after-wled"></a></p><h2 id="warum-funktioniert-der-adapter-nach-einem-wled-firmware-update-nicht-mehr-oder-segmente-nur-an-einem-gerat" tabindex="-1">Warum funktioniert der Adapter nach einem WLED-Firmware-Update nicht mehr, oder Segmente nur an einem Gerät? <a class="header-anchor" href="#warum-funktioniert-der-adapter-nach-einem-wled-firmware-update-nicht-mehr-oder-segmente-nur-an-einem-gerat" aria-label="Permalink to &quot;Warum funktioniert der Adapter nach einem WLED-Firmware-Update nicht mehr, oder Segmente nur an einem Gerät?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="wled-shown-offline-after-restart"></a></p><h2 id="warum-wird-wled-nach-neustart-oder-update-als-offline-angezeigt-und-verbindet-sich-lange-nicht" tabindex="-1">Warum wird WLED nach Neustart oder Update als offline angezeigt und verbindet sich lange nicht? <a class="header-anchor" href="#warum-wird-wled-nach-neustart-oder-update-als-offline-angezeigt-und-verbindet-sich-lange-nicht" aria-label="Permalink to &quot;Warum wird WLED nach Neustart oder Update als offline angezeigt und verbindet sich lange nicht?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="wled-devices-show-red-offline"></a></p><h2 id="warum-zeigen-alle-wled-rot-oder-offline-oder-der-esp-sturzt-ab" tabindex="-1">Warum zeigen alle WLED rot oder offline, oder der ESP stürzt ab? <a class="header-anchor" href="#warum-zeigen-alle-wled-rot-oder-offline-oder-der-esp-sturzt-ab" aria-label="Permalink to &quot;Warum zeigen alle WLED rot oder offline, oder der ESP stürzt ab?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="about-multiple-adapter-processes-already"></a></p><h2 id="was-tue-ich-bei-mehreren-adapter-prozessen-oder-already-running-und-onunload-fehlern" tabindex="-1">Was tue ich bei mehreren Adapter-Prozessen oder &quot;already running&quot; und onUnload-Fehlern? <a class="header-anchor" href="#was-tue-ich-bei-mehreren-adapter-prozessen-oder-already-running-und-onunload-fehlern" aria-label="Permalink to &quot;Was tue ich bei mehreren Adapter-Prozessen oder &quot;already running&quot; und onUnload-Fehlern?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>',31)])])}const b=t(d,[["render",o]]);export{m as __pageData,b as default};
